// Desktop shares the phone's mounted panels, grouped into two workspaces.
// Switching sections changes visibility only; drafts and pending work survive.
const PAGES = ['daily', 'games'];
const STORAGE_KEY = 'desktopSections.page';
const desktop = window.matchMedia('(min-width: 1100px)');
const body = document.body;
const tutorial = new URLSearchParams(location.search).get('tutorial') === '1';
if (tutorial) delete body.dataset.desktopPage;
const main = document.querySelector('#app-workspace');
const navigation = document.querySelector('.desktop-sections');
const pageLink = document.querySelector('[data-desktop-page-link]');
const scrollPositions = new Map();
let current = PAGES.includes(body.dataset.desktopPage) ? body.dataset.desktopPage : 'daily';

function publish() {
  document.dispatchEvent(new CustomEvent('desktop-sections:change', { detail: { page: current } }));
}

function paintNavigation() {
  const button = navigation.querySelector('[data-desktop-switch]');
  const next = current === 'daily' ? 'games' : 'daily';
  button.textContent = current === 'daily' ? 'GAMES →' : '← DAILY';
  button.setAttribute('aria-label', `Go to ${next}`);
  button.title = current === 'daily' ? 'Play Craps and Degenerette' : 'Daily drawing, Buy In and Coinflip';
  if (pageLink) {
    pageLink.querySelector('.desktop-page-link__label').textContent = current === 'daily' ? 'GAMES' : 'DAILY';
    pageLink.querySelector('.desktop-page-link__arrow').textContent = current === 'daily' ? '→' : '←';
    pageLink.setAttribute('aria-label', current === 'daily' ? 'More games: Craps and Degenerette' : 'Back to Daily games');
    pageLink.title = button.title;
  }
  if (desktop.matches) main.setAttribute('aria-label', current === 'daily' ? 'Daily games' : 'Craps and Degenerette');
  else main.removeAttribute('aria-label');
}

export function showDesktopSection(page, { focus = false } = {}) {
  if (!main || !navigation || !desktop.matches || !PAGES.includes(page)) return;
  if (page !== current) {
    scrollPositions.set(current, main.scrollTop);
    current = page;
    body.dataset.desktopPage = page;
    main.scrollTo({ top: scrollPositions.get(page) ?? 0, behavior: 'instant' });
    try { sessionStorage.setItem(STORAGE_KEY, page); } catch (_) { /* private mode */ }
    publish();
  }
  paintNavigation();
  if (focus) navigation.querySelector('[data-desktop-switch]').focus();
}

if (main && navigation && !tutorial) {
  const chrome = document.querySelector('.unified-nav');
  const auth = chrome?.querySelector('.nav-auth');
  if (auth) auth.before(navigation);
  else chrome?.append(navigation);
  try {
    const restored = sessionStorage.getItem(STORAGE_KEY);
    if (PAGES.includes(restored)) current = restored;
  } catch (_) { /* private mode */ }
  body.dataset.desktopPage = current;
  paintNavigation();

  for (const control of [navigation, pageLink]) {
    control?.addEventListener('click', event => {
      if (event.target.closest('[data-desktop-switch], [data-desktop-page-link]')) showDesktopSection(current === 'daily' ? 'games' : 'daily');
    });
    control?.addEventListener('keydown', event => {
      const trigger = event.target.closest('[data-desktop-switch], [data-desktop-page-link]');
      if (!trigger) return;
      const index = PAGES.indexOf(current);
      const next = ({ ArrowRight: (index + 1) % PAGES.length, ArrowLeft: (index + PAGES.length - 1) % PAGES.length,
        Home: 0, End: PAGES.length - 1 })[event.key];
      if (next == null) return;
      event.preventDefault();
      showDesktopSection(PAGES[next]);
      trigger.focus();
    });
  }
  // Quest and Pending shortcuts already scroll their owning component into
  // view. Reveal that section first, including when it has not loaded yet.
  const nativeScrollIntoView = Element.prototype.scrollIntoView;
  Element.prototype.scrollIntoView = function scrollIntoDesktopSection(...args) {
    if (desktop.matches && !this.closest('[hidden]')) {
      const page = this.closest('[data-dpage]')?.dataset.dpage?.split(/\s+/)[0];
      if (page) showDesktopSection(page);
    }
    return nativeScrollIntoView.apply(this, args);
  };

  desktop.addEventListener('change', () => {
    paintNavigation();
    if (desktop.matches) main.scrollTo({ top: scrollPositions.get(current) ?? 0, behavior: 'instant' });
    publish();
  });
  // Give the controls their natural height, then use the remaining room for
  // the headline. Observing the actual panels also covers loaded balances,
  // the testnet strip, browser zoom and a taller information panel.
  const headline = main.querySelector('gold-rush-headline');
  let fitting = false;
  const fitHeadline = () => {
    fitting = false;
    if (!desktop.matches) return;
    const style = getComputedStyle(main);
    // Size the games to the space left by the actual navigation and bottom
    // bar, including wrapped navigation, browser zoom and the testnet strip.
    const gameHeight = `${Math.max(0, Math.floor(main.clientHeight - parseFloat(style.paddingTop) - parseFloat(style.paddingBottom) - 2))}px`;
    if (body.style.getPropertyValue('--desktop-game-height') !== gameHeight) body.style.setProperty('--desktop-game-height', gameHeight);
    if (current !== 'daily' || !headline) return;
    const panels = [...main.children].filter(el => {
      const css = getComputedStyle(el);
      return css.display !== 'none' && css.position !== 'fixed' && css.position !== 'absolute' && el.getBoundingClientRect().height > 0;
    });
    const used = panels.filter(el => el !== headline).reduce((sum, el) => sum + el.getBoundingClientRect().height, 0);
    const spacing = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom)
      + Math.max(0, panels.length - 1) * (parseFloat(style.rowGap) || 0);
    const minimum = main.clientHeight < 650 ? 80 : 110;
    const height = Math.floor(Math.max(minimum, Math.min(240, main.clientWidth * 400 / 2172, main.clientHeight - used - spacing - 2)));
    const value = `${height}px`;
    if (body.style.getPropertyValue('--desktop-headline-height') !== value) body.style.setProperty('--desktop-headline-height', value);
  };
  const queueFit = () => { if (!fitting) { fitting = true; requestAnimationFrame(fitHeadline); } };
  if (typeof ResizeObserver === 'function') {
    const observer = new ResizeObserver(queueFit);
    observer.observe(main);
    for (const child of main.children) if (!child.classList.contains('info-rail')) observer.observe(child);
  }
  document.addEventListener('desktop-sections:change', queueFit);
  desktop.addEventListener('change', queueFit);
  queueFit();
  publish();
}
